func TestActivityGuardFooterBrailleLogic(t *testing.T) {
	if got := footerBrailleProblem("  1 job running"); got != "" {
		t.Errorf("a clean footer: %s", got)
	}
	if got := footerBrailleProblem("  ⠹ 1 job running"); got == "" {
		t.Error("a footer with a braille frame passed")
